// Bivariate Choropleth — Geo, route: jsx
// Source: bivariate-choropleth
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

// ---- inlined from bivariateChoropleth ----
// Synthetic stand-in for the CDC county diabetes/obesity table the notebook loads.
// Deterministic: every rate is a pure function of the state's FIPS id.

/** geoAlbersUsa projects none of these, so they are dropped before fitting. */
const TERRITORY_IDS = new Set(['60', '66', '69', '72', '78']);

type StateRates = { diabetes: number; obesity: number };

/** FNV-1a over the key, folded into [0, 1). */
function hash(key: string): number {
  let h = 2166136261;
  for (let index = 0; index < key.length; index++) {
    h = Math.imul(h ^ key.charCodeAt(index), 16777619);
  }
  return (h >>> 0) / 4294967296;
}

// A shared latent term correlates the two rates at roughly 0.4. Fully independent
// draws scatter the 3x3 matrix; a stronger tie collapses it onto the diagonal.
function stateRates(id: string): StateRates {
  const shared = hash(`${id}:latent`);
  const mix = (own: number) => 0.45 * shared + 0.55 * own;
  return {
    diabetes: Math.round((6 + 10 * mix(hash(`${id}:diabetes`))) * 10) / 10,
    obesity: Math.round((24 + 20 * mix(hash(`${id}:obesity`))) * 10) / 10
  };
}

function isTerritory(id: string): boolean {
  return TERRITORY_IDS.has(id);
}

const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };
const N = 3;
const LABELS = ['low', '', 'high'];

// Joshua Stevens' BuPu bivariate matrix, row-major: diabetes level * N + obesity level.
const COLORS = [
  '#e8e8e8', '#ace4e4', '#5ac8c8',
  '#dfb0d6', '#a5add3', '#5698b9',
  '#be64ac', '#8c62aa', '#3b4994'
];

// usStatesCollection is already filtered to what geoAlbersUsa can project.
const states = usStatesCollection;
const borders = usStateBorders;

/** Two rates per state FIPS id; their quantile levels pick a cell of the 3x3 matrix. */
export type Data = Record<string, { diabetes: number; obesity: number }>;

const DEMO: Data = Object.fromEntries(
  states.features.map((f) => [String(f.id), stateRates(String(f.id))])
);

export default function BivariateChoropleth({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.6);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const { path, marks } = useMemo(() => {
    const projection = d3.geoAlbersUsa().fitSize([innerWidth, innerHeight], states);
    const geoPath = d3.geoPath(projection);

    const rates = states.features.map((f) => data[String(f.id)]);
    const level = {
      diabetes: d3.scaleQuantile(rates.map((d) => d.diabetes), d3.range(N)),
      obesity: d3.scaleQuantile(rates.map((d) => d.obesity), d3.range(N))
    };

    return {
      path: geoPath,
      marks: states.features.map((f, index) => {
        const { diabetes, obesity } = rates[index];
        const row = level.diabetes(diabetes);
        const column = level.obesity(obesity);
        return {
          id: String(f.id),
          name: f.properties.name,
          d: geoPath(f) ?? '',
          fill: COLORS[row * N + column],
          title: `${f.properties.name}\n${diabetes}% diabetes (${LABELS[row] || 'medium'})\n${obesity}% obesity (${LABELS[column] || 'medium'})`
        };
      })
    };
  }, [data, innerWidth, innerHeight]);

  if (width === 0) return null;

  const legendCell = Math.max(13, Math.round(width * 0.023));
  const legendSide = legendCell * N;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Bivariate choropleth of diabetes and obesity prevalence by US state">
      <defs>
        <marker id="bivariate-arrow" markerHeight={10} markerWidth={10} refX={6} refY={3}
                orient="auto">
          <path d="M0,0L9,3L0,6Z" fill="var(--muted)" />
        </marker>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {marks.map((m) => (
          <path key={m.id} d={m.d} fill={m.fill}>
            <title>{m.title}</title>
          </path>
        ))}
        <path d={path(borders) ?? ''} fill="none" stroke="var(--bg)" strokeLinejoin="round" />
        <g transform={`translate(${innerWidth - legendSide * 1.15},${innerHeight - legendSide * 1.25})`}>
          <BivariateLegend cell={legendCell} />
        </g>
      </g>
    </svg>
  );
}

/** The 3x3 matrix itself, rotated 45 degrees so both axes read as arrows. */
function BivariateLegend({ cell }: { cell: number }) {
  const side = cell * N;
  const half = side / 2;
  const swatches = d3.cross(d3.range(N), d3.range(N));

  return (
    <g fontSize={Math.max(8, Math.round(cell * 0.45))} fill="var(--muted)"
       transform={`translate(${-half},${-half}) rotate(-45 ${half} ${half})`}>
      {swatches.map(([column, row]) => (
        <rect
          key={`${column}-${row}`}
          x={column * cell}
          y={(N - 1 - row) * cell}
          width={cell}
          height={cell}
          fill={COLORS[row * N + column]}
        />
      ))}
      <line x1={0} x2={side} y1={side} y2={side} stroke="var(--muted)" strokeWidth={1.5}
            markerEnd="url(#bivariate-arrow)" />
      <line x1={0} x2={0} y1={side} y2={0} stroke="var(--muted)" strokeWidth={1.5}
            markerEnd="url(#bivariate-arrow)" />
      <text fontWeight="bold" dy="0.71em" textAnchor="middle"
            transform={`rotate(90) translate(${half},6)`}>
        Diabetes
      </text>
      <text fontWeight="bold" dy="0.71em" textAnchor="middle"
            transform={`translate(${half},${side + 6})`}>
        Obesity
      </text>
    </g>
  );
}
